static int token_continue ( i_ctx_t * i_ctx_p , scanner_state * pstate , bool save ) {
 os_ptr op = osp ;
 int code ;
 ref token ;
 pop ( 1 ) ;
 again : code = gs_scan_token ( i_ctx_p , & token , pstate ) ;
 op = osp ;
 switch ( code ) {
 default : if ( code > 0 ) code = gs_note_error ( gs_error_syntaxerror ) ;
